# Adaptive rejection sampling (Gilks & Wild, 1992)
# ---------------------------------------------------------------------------
# Public interface:
#   ars(n, density, lower = -Inf, upper = Inf, init = NULL, ...)
#   test(n = 5000, seed = 20240101, write_files = TRUE)
#
# The density may be a vectorised R function (e.g. dnorm) or a character
# expression in x (e.g. "exp(-x^2/2)").  It need not be normalised.
# ---------------------------------------------------------------------------


# ===========================================================================
# 1. Input validation and construction of the log-density
# ===========================================================================

ars_validate_n <- function(n) {
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || !is.finite(n)) {
    stop("'n' must be a single finite number.", call. = FALSE)
  }
  if (n < 0) {
    stop("'n' must be non-negative.", call. = FALSE)
  }
  if (n < 1) {
    stop("'n' must be at least 1.", call. = FALSE)
  }
  if (abs(n - round(n)) > .Machine$double.eps^0.5) {
    stop("'n' must be an integer.", call. = FALSE)
  }
  as.integer(round(n))
}

ars_validate_domain <- function(lower, upper) {
  if (!is.numeric(lower) || length(lower) != 1L || is.na(lower)) {
    stop("'lower' must be a single numeric value.", call. = FALSE)
  }
  if (!is.numeric(upper) || length(upper) != 1L || is.na(upper)) {
    stop("'upper' must be a single numeric value.", call. = FALSE)
  }
  if (lower >= upper) {
    stop("'lower' must be strictly less than 'upper'.", call. = FALSE)
  }
  invisible(TRUE)
}

ars_density_from_input <- function(density, ...) {
  if (is.function(density)) {
    return(function(x) density(x, ...))
  }
  if (is.character(density) && length(density) == 1L) {
    expr <- tryCatch(parse(text = density)[[1L]],
                     error = function(e)
                       stop("Could not parse the density expression: ", e$message,
                            call. = FALSE))
    caller <- parent.frame()
    return(function(x) {
      eval(expr, envir = list(x = x), enclos = caller)
    })
  }
  if (is.language(density) || is.expression(density)) {
    expr <- if (is.expression(density)) density[[1L]] else density
    caller <- parent.frame()
    return(function(x) eval(expr, envir = list(x = x), enclos = caller))
  }
  stop("'density' must be a function or a character expression in 'x'.",
       call. = FALSE)
}

ars_validate_density <- function(density_fun, lower, upper) {
  pts <- ars_validation_points(lower, upper)
  vals <- tryCatch(density_fun(pts),
                   error = function(e)
                     stop("The density function failed: ", e$message,
                          call. = FALSE))
  if (!is.numeric(vals)) {
    stop("The density function must return a numeric vector.", call. = FALSE)
  }
  if (length(vals) != length(pts)) {
    stop("The density function must be vectorised (return one value per input).",
         call. = FALSE)
  }
  if (anyNA(vals)) {
    stop("The density function returned missing values.", call. = FALSE)
  }
  if (any(vals < 0)) {
    stop("The density function returned negative values.", call. = FALSE)
  }
  if (any(is.infinite(vals))) {
    stop("The density function returned infinite values.", call. = FALSE)
  }
  if (!any(vals > 0)) {
    stop("The density function is zero at every validation point; ",
         "check its support and the domain.", call. = FALSE)
  }
  invisible(TRUE)
}

# Broad, deterministic grid used for input validation and for locating
# initial abscissae.  It covers the whole real line when the domain is
# unbounded, with geometric expansion into the tails.
ars_default_grid <- function(lower, upper) {
  if (is.finite(lower) && is.finite(upper)) {
    return(seq(lower, upper, length.out = 2001L))
  }
  if (is.finite(lower)) {
    base <- seq(0, 20, length.out = 801L)
    ext <- 20 * 2^(0:8)
    return(unique(lower + c(base, ext)))
  }
  if (is.finite(upper)) {
    base <- seq(0, 20, length.out = 801L)
    ext <- 20 * 2^(0:8)
    return(sort(unique(upper - c(base, ext))))
  }
  c(seq(-20, 20, length.out = 801L),
    -20 * 2^(0:8), 20 * 2^(0:8)) |>
    unique() |>
    sort()
}

ars_validation_points <- function(lower, upper) {
  g <- ars_default_grid(lower, upper)
  idx <- unique(round(seq(1L, length(g), length.out = min(151L, length(g)))))
  # Always include a few points near the origin, which helps for densities
  # centred away from the grid's densest region.
  extra <- c(-1, 0, 1)
  extra <- extra[extra > lower & extra < upper]
  sort(unique(c(g[idx][g[idx] > lower & g[idx] < upper], extra)))
}


# ===========================================================================
# 2. Log-density and numerical derivatives
# ===========================================================================

ars_make_log_density <- function(density_fun) {
  function(x) {
    v <- density_fun(x)
    if (length(v) != length(x)) {
      stop("The density function stopped being vectorised inside 'ars'.",
           call. = FALSE)
    }
    out <- rep(-Inf, length(v))
    pos <- v > 0
    out[pos] <- log(v[pos])
    out
  }
}

# Central difference where possible, one-sided difference at a support
# boundary (where the density is zero on one side).
ars_log_derivative <- function(log_den, x, lower, upper) {
  h0 <- log_den(x)
  if (length(h0) != 1L || !is.finite(h0)) {
    stop("Cannot differentiate the log-density at x = ", format(x), ".",
         call. = FALSE)
  }
  base_step <- 1e-4 * max(1, abs(x))
  for (k in 0:25) {
    step <- base_step / 2^k
    xl <- x - step
    xr <- x + step
    in_l <- xl >= lower
    in_r <- xr <= upper
    if (in_l && in_r) {
      hl <- log_den(xl)
      hr <- log_den(xr)
      if (is.finite(hl) && is.finite(hr)) {
        return((hr - hl) / (2 * step))
      }
    }
    if (in_l) {
      hl <- log_den(xl)
      if (is.finite(hl)) return((h0 - hl) / step)
    }
    if (in_r) {
      hr <- log_den(xr)
      if (is.finite(hr)) return((hr - h0) / step)
    }
  }
  stop("Could not compute a numerical derivative of the log-density at x = ",
       format(x), ".", call. = FALSE)
}


# ===========================================================================
# 3. Initial abscissae
# ===========================================================================

ars_initial_abscissae <- function(log_den, lower, upper, n_init = 4L,
                                  init = NULL) {
  if (!is.null(init)) {
    if (!is.numeric(init) || length(init) < 3L || anyNA(init) ||
        any(!is.finite(init))) {
      stop("'init' must contain at least three finite numeric values.",
           call. = FALSE)
    }
    if (any(init < lower) || any(init > upper)) {
      stop("All values in 'init' must lie inside [lower, upper].",
           call. = FALSE)
    }
    xs <- sort(unique(init))
    if (length(xs) < 3L) {
      stop("'init' must contain at least three distinct values.", call. = FALSE)
    }
    hs <- log_den(xs)
    if (any(!is.finite(hs))) {
      stop("Every value in 'init' must have positive, finite density.",
           call. = FALSE)
    }
    return(list(x = xs, h = hs, lower = lower, upper = upper))
  }

  grid <- ars_default_grid(lower, upper)
  hgrid <- log_den(grid)
  ok <- is.finite(hgrid)
  if (sum(ok) < 3L) {
    stop("Could not find three points with positive density; ",
         "check the density and domain.", call. = FALSE)
  }

  # Locate the contiguous region of finite log-density containing the mode.
  best <- which(ok)[which.max(hgrid[ok])]
  l <- best
  while (l > 1L && ok[l - 1L]) l <- l - 1L
  r <- best
  while (r < length(grid) && ok[r + 1L]) r <- r + 1L
  if (r - l + 1L < 3L) {
    stop("Could not find three abscissae with positive density.", call. = FALSE)
  }

  idx <- unique(round(seq(l, r, length.out = max(3L, n_init))))
  xs <- grid[idx]
  hs <- hgrid[idx]

  # If the region of finite density does not reach the grid boundary, the
  # density has (numerically) compact support: restrict the sampling domain
  # to the discovered support.  This avoids trying to build an improper
  # exponential envelope beyond a support boundary.
  lower_eff <- lower
  upper_eff <- upper
  if (l > 1L) lower_eff <- grid[l]
  if (r < length(grid)) upper_eff <- grid[r]

  list(x = xs, h = hs, lower = lower_eff, upper = upper_eff)
}


# ===========================================================================
# 4. Log-concavity checks
# ===========================================================================

# A differentiable function is log-concave iff the slopes of its log-density
# on consecutive abscissae are non-increasing.
ars_check_concavity_values <- function(x, h, tol = 1e-6) {
  if (length(x) < 3L) return(invisible(TRUE))
  slopes <- diff(h) / diff(x)
  scale <- max(1, max(abs(slopes)))
  if (any(diff(slopes) > tol * scale)) {
    bad <- which.max(diff(slopes))
    stop("Non-log-concave density detected: the slope of the log-density ",
         "increases between x = ", format(x[bad]), " and x = ",
         format(x[bad + 2L]), ". Adaptive rejection sampling requires a ",
         "log-concave density.", call. = FALSE)
  }
  invisible(TRUE)
}

ars_check_log_concavity <- function(log_den, x, tol = 1e-6) {
  xs <- sort(unique(x))
  hs <- log_den(xs)
  if (any(!is.finite(hs))) {
    stop("Cannot check log-concavity: non-finite log-density values.",
         call. = FALSE)
  }
  ars_check_concavity_values(xs, hs, tol = tol)
}


# ===========================================================================
# 5. Upper and lower hulls
# ===========================================================================

# Tangent lines to h at the abscissae.  The upper hull is their pointwise
# minimum; with log-concavity it is piecewise linear with the tangents meeting
# between consecutive abscissae.
ars_upper_hull <- function(x, h, dh, lower, upper) {
  k <- length(x)
  slope <- dh
  intercept <- h - dh * x
  breaks <- rep(NA_real_, k + 1L)
  breaks[1L] <- lower
  breaks[k + 1L] <- upper

  if (k >= 2L) {
    for (i in seq_len(k - 1L)) {
      if (abs(slope[i] - slope[i + 1L]) < 1e-12) {
        # Equal slopes: for a concave function the tangents coincide on the
        # interval; any point in the interval can be used as the join.
        z <- (x[i] + x[i + 1L]) / 2
      } else {
        z <- (intercept[i + 1L] - intercept[i]) /
          (slope[i] - slope[i + 1L])
      }
      # Tiny numerical excursions outside the interval are clamped.  A large
      # excursion is a symptom of a non-log-concave density.
      width <- x[i + 1L] - x[i]
      if (z < x[i] - 1e-6 * max(1, width) ||
          z > x[i + 1L] + 1e-6 * max(1, width)) {
        stop("Non-log-concave density detected: tangent lines at x = ",
             format(x[i]), " and x = ", format(x[i + 1L]),
             " do not meet between the abscissae.", call. = FALSE)
      }
      breaks[i + 1L] <- min(max(z, x[i]), x[i + 1L])
    }
  }

  if (any(diff(breaks) <= 0)) {
    stop("Degenerate upper hull: abscissae or breakpoints are not distinct.",
         call. = FALSE)
  }
  list(x = x, h = h, dh = dh, slope = slope, intercept = intercept,
       breaks = breaks)
}

ars_upper_hull_value <- function(newx, hull) {
  k <- length(hull$x)
  idx <- findInterval(newx, hull$breaks, all.inside = TRUE)
  idx <- pmin(pmax(idx, 1L), k)
  hull$slope[idx] * newx + hull$intercept[idx]
}

ars_lower_hull_value <- function(newx, x, h) {
  k <- length(x)
  res <- rep(-Inf, length(newx))
  if (k < 2L) return(res)
  inside <- newx >= x[1L] & newx <= x[k]
  if (!any(inside)) return(res)
  xi <- newx[inside]
  idx <- findInterval(xi, x)
  idx <- pmin(idx, k - 1L)
  t <- (xi - x[idx]) / (x[idx + 1L] - x[idx])
  res[inside] <- h[idx] + t * (h[idx + 1L] - h[idx])
  res
}

# Log of the integral of exp(upper hull) over each piece.  This is what makes
# it possible to draw directly from the piecewise-exponential envelope.
ars_log_segment_integrals <- function(hull) {
  k <- length(hull$x)
  L <- hull$breaks[-(k + 1L)]
  R <- hull$breaks[-1L]
  a <- hull$slope
  b <- hull$intercept
  log_i <- rep(NA_real_, k)

  for (j in seq_len(k)) {
    if (!is.finite(L[j]) && !is.finite(R[j])) {
      stop("Invalid envelope: an infinite segment on both sides.",
           call. = FALSE)
    }
    if (abs(a[j]) < 1e-12) {
      if (!is.finite(L[j]) || !is.finite(R[j])) {
        stop("The exponential envelope has an improper tail (zero slope). ",
             "The density may not be integrable on the requested domain.",
             call. = FALSE)
      }
      log_i[j] <- b[j] + log(R[j] - L[j])
    } else if (!is.finite(L[j])) {
      # (-Inf, R]: integrable only when the slope is positive.
      if (a[j] <= 0) {
        stop("The exponential envelope has an improper left tail. ",
             "The density may not be integrable on the requested domain.",
             call. = FALSE)
      }
      log_i[j] <- a[j] * R[j] + b[j] - log(a[j])
    } else if (!is.finite(R[j])) {
      # [L, Inf): integrable only when the slope is negative.
      if (a[j] >= 0) {
        stop("The exponential envelope has an improper right tail. ",
             "The density may not be integrable on the requested domain.",
             call. = FALSE)
      }
      log_i[j] <- a[j] * L[j] + b[j] - log(-a[j])
    } else {
      m <- max(a[j] * L[j], a[j] * R[j])
      num <- exp(a[j] * R[j] - m) - exp(a[j] * L[j] - m)
      log_i[j] <- b[j] + m + log(num / a[j])
    }
    if (!is.finite(log_i[j])) {
      stop("Could not compute a finite envelope integral on segment ", j,
           "; the density may not be integrable on the requested domain.",
           call. = FALSE)
    }
  }
  log_i
}

# Draw one candidate from the piecewise-exponential upper hull.
ars_sample_upper_hull <- function(hull) {
  k <- length(hull$x)
  log_i <- ars_log_segment_integrals(hull)
  w <- exp(log_i - max(log_i))
  j <- sample.int(k, size = 1L, prob = w)

  L <- hull$breaks[j]
  R <- hull$breaks[j + 1L]
  a <- hull$slope[j]
  b <- hull$intercept[j]
  u <- runif(1L)

  if (!is.finite(L)) {
    # Left tail, necessarily a > 0.
    return(R + log(u) / a)
  }
  if (!is.finite(R)) {
    # Right tail, necessarily a < 0.
    return(L + log1p(-u) / a)
  }
  if (abs(a) < 1e-12) {
    return(L + u * (R - L))
  }
  m <- max(a * L, a * R)
  (m + log(exp(a * L - m) + u * (exp(a * R - m) - exp(a * L - m)))) / a
}


# ===========================================================================
# 6. Main adaptive rejection sampler
# ===========================================================================

ars <- function(n, density, lower = -Inf, upper = Inf, init = NULL, ...) {
  n <- ars_validate_n(n)
  ars_validate_domain(lower, upper)

  density_fun <- ars_density_from_input(density, ...)
  ars_validate_density(density_fun, lower, upper)
  log_den <- ars_make_log_density(density_fun)

  start <- ars_initial_abscissae(log_den, lower, upper, n_init = 4L,
                                 init = init)
  xs <- start$x
  hs <- start$h
  lower_eff <- start$lower
  upper_eff <- start$upper
  ars_check_concavity_values(xs, hs)

  dhs <- vapply(xs, function(z)
    ars_log_derivative(log_den, z, lower_eff, upper_eff), numeric(1))
  hull <- ars_upper_hull(xs, hs, dhs, lower_eff, upper_eff)

  samples <- numeric(n)
  n_done <- 0L
  n_squeezed <- 0L
  n_evaluated <- 0L
  n_rejected <- 0L
  # A safety valve against an accidentally non-integrable / pathological input.
  max_iter <- max(1000L, 200L * n)
  iter <- 0L

  while (n_done < n) {
    iter <- iter + 1L
    if (iter > max_iter) {
      stop("Sampling did not complete within the iteration limit; ",
           "the density may not be log-concave or may not be integrable.",
           call. = FALSE)
    }

    cand <- ars_sample_upper_hull(hull)

    if (!is.finite(cand) || cand < lower_eff || cand > upper_eff) {
      n_rejected <- n_rejected + 1L
      next
    }

    log_u <- log(runif(1L))
    upper_value <- ars_upper_hull_value(cand, hull)
    lower_value <- ars_lower_hull_value(cand, hull$x, hull$h)

    # Squeezing test: no evaluation of the density is needed.
    if (log_u <= lower_value - upper_value) {
      n_done <- n_done + 1L
      samples[n_done] <- cand
      n_squeezed <- n_squeezed + 1L
      next
    }

    # Otherwise evaluate the target log-density.
    h_cand <- log_den(cand)
    n_evaluated <- n_evaluated + 1L

    # During sampling, the envelope must dominate the log-density.  A
    # violation is direct evidence that log-concavity fails.
    hull_tol <- 1e-6 * (1 + abs(upper_value))
    if (is.finite(h_cand) && h_cand > upper_value + hull_tol) {
      stop("Non-log-concave density detected during sampling: at x = ",
           format(cand), " the log-density (", format(h_cand),
           ") exceeds the upper hull (", format(upper_value),
           "). Adaptive rejection sampling requires a log-concave density.",
           call. = FALSE)
    }

    if (log_u <= h_cand - upper_value) {
      n_done <- n_done + 1L
      samples[n_done] <- cand
    } else {
      n_rejected <- n_rejected + 1L
    }

    # Adapt: add the evaluated point to the abscissae if it is new and has a
    # finite log-density.
    if (is.finite(h_cand) &&
        !any(abs(cand - hull$x) <= 1e-12 * max(1, abs(cand)))) {
      ord <- order(c(hull$x, cand))
      xs_new <- c(hull$x, cand)[ord]
      hs_new <- c(hull$h, h_cand)[ord]
      dh_new <- c(hull$dh,
                  ars_log_derivative(log_den, cand, lower_eff,
                                     upper_eff))[ord]
      ars_check_concavity_values(xs_new, hs_new)
      hull <- ars_upper_hull(xs_new, hs_new, dh_new, lower_eff, upper_eff)
    }
  }

  structure(samples,
            class = "ars_result",
            n = n,
            domain = c(lower_eff, upper_eff),
            n_abscissae = length(hull$x),
            n_evaluated = n_evaluated,
            n_squeezed = n_squeezed,
            n_rejected = n_rejected)
}

print.ars_result <- function(x, ...) {
  cat("Adaptive rejection sample of size", attr(x, "n"), "\n")
  cat("  sampling domain:", attr(x, "domain")[1L], "to",
      attr(x, "domain")[2L], "\n")
  cat("  final abscissae:", attr(x, "n_abscissae"),
      "| density evaluations:", attr(x, "n_evaluated"),
      "| squeezed:", attr(x, "n_squeezed"),
      "| rejected:", attr(x, "n_rejected"), "\n")
  invisible(x)
}


# ===========================================================================
# 7. Formal tests
# ===========================================================================

ars_test_report <- function(name, passed, mean_value = NA_real_,
                            sd_value = NA_real_, detail = NULL) {
  if (!is.null(detail) && nzchar(detail)) {
    cat("  Detail:", detail, "\n")
  }
  cat(sprintf("  %s: mean = %s, sd = %s\n", name,
              ars_format_stat(mean_value), ars_format_stat(sd_value)))
  cat(sprintf("%s: %s\n", name, if (isTRUE(passed)) "PASS" else "FAIL"))
  data.frame(test = name, passed = isTRUE(passed),
             mean = mean_value, sd = sd_value,
             stringsAsFactors = FALSE)
}

ars_format_stat <- function(v) {
  if (length(v) != 1L || is.na(v)) return("NA")
  formatC(v, format = "f", digits = 6)
}

ars_expect_error <- function(expr) {
  inherits(try(expr, silent = TRUE), "try-error")
}

test <- function(n = 5000L, seed = 20240101L, write_files = TRUE) {
  n <- ars_validate_n(n)
  set.seed(seed)
  cat("Adaptive rejection sampler test suite\n")
  cat("=====================================\n")
  cat("Sample size per distribution:", n, "| RNG seed:", seed, "\n\n")
  results <- list()

  # -----------------------------------------------------------------------
  cat("[1] Input validation\n")
  checks <- c(
    negative_n        = ars_expect_error(ars(-5, dnorm)),
    zero_n            = ars_expect_error(ars(0, dnorm)),
    non_integer_n     = ars_expect_error(ars(2.5, dnorm)),
    reversed_domain   = ars_expect_error(ars(20, dnorm, lower = 2, upper = -2)),
    non_numeric_lower = ars_expect_error(ars(20, dnorm, lower = "a")),
    invalid_density   = ars_expect_error(ars(20, "this is not valid R code !")),
    non_vectorised    = ars_expect_error(ars(20, function(x) 1)),
    short_init        = ars_expect_error(ars(20, dnorm, init = c(0, 1)))
  )
  failed <- names(checks)[!checks]
  detail <- if (length(failed)) {
    paste("not rejected:", paste(failed, collapse = ", "))
  } else {
    "all invalid inputs were rejected with informative errors"
  }
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_INPUT_VALIDATION", all(checks),
                    detail = detail)

  # -----------------------------------------------------------------------
  cat("\n[2] Hull construction module\n")
  xs <- c(-2, -0.5, 0.5, 2)
  hs <- log(dnorm(xs))
  dhs <- -xs
  hull <- ars_upper_hull(xs, hs, dhs, -Inf, Inf)
  grid <- seq(-5, 5, length.out = 1001L)
  truth <- log(dnorm(grid))
  upper_vals <- ars_upper_hull_value(grid, hull)
  lower_vals <- ars_lower_hull_value(grid, xs, hs)
  upper_ok <- all(upper_vals >= truth - 1e-9)
  in_range <- grid >= min(xs) & grid <= max(xs)
  lower_ok <- all(lower_vals[in_range] <= truth[in_range] + 1e-9)
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_UPPER_HULL_BOUND", upper_ok,
                    mean(truth - upper_vals), sd(truth - upper_vals),
                    "upper hull must dominate the true log-density")
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_LOWER_HULL_BOUND", lower_ok,
                    mean(lower_vals[in_range] - truth[in_range]),
                    sd(lower_vals[in_range] - truth[in_range]),
                    "lower hull must lie below the true log-density")

  # -----------------------------------------------------------------------
  cat("\n[3] Log-concavity-check module\n")
  concave_ok <- !ars_expect_error(
    ars_check_log_concavity(ars_make_log_density(dnorm),
                            seq(-3, 3, length.out = 25L)))
  convex_rejected <- ars_expect_error(
    ars_check_log_concavity(ars_make_log_density(dcauchy),
                            seq(-8, 8, length.out = 41L)))
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_CONCAVITY_CHECK", concave_ok && convex_rejected,
                    NA_real_, NA_real_,
                    paste("normal accepted:", concave_ok,
                          "| Cauchy rejected:", convex_rejected))

  # -----------------------------------------------------------------------
  cat("\n[4] Non-log-concave density detection during ars()\n")
  err_msg <- tryCatch({
    ars(500, dcauchy)
    ""
  }, error = function(e) conditionMessage(e))
  nc_pass <- nzchar(err_msg) &&
    grepl("log-concave", err_msg, ignore.case = TRUE)
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_NON_LOG_CONCAVE_ERROR", nc_pass,
                    NA_real_, NA_real_,
                    if (nzchar(err_msg)) err_msg else
                      "Cauchy density was not rejected")

  # -----------------------------------------------------------------------
  cat("\n[5] Normal(0, 1) sampling\n")
  cat("  Drawing", n, "samples with dnorm ...\n")
  normal_samples <- as.numeric(ars(n, dnorm))
  normal_mean <- mean(normal_samples)
  normal_sd <- sd(normal_samples)
  normal_ks <- suppressWarnings(ks.test(normal_samples, "pnorm")$p.value)
  normal_pass <- abs(normal_mean) < 0.1 &&
    abs(normal_sd - 1) < 0.1 && normal_ks > 1e-3
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_NORMAL_DISTRIBUTION", normal_pass,
                    normal_mean, normal_sd,
                    sprintf("target mean 0, target sd 1, KS p-value %.4g",
                            normal_ks))

  # -----------------------------------------------------------------------
  cat("\n[6] Exponential(rate = 2) sampling\n")
  cat("  Drawing", n, "samples with dexp(rate = 2) ...\n")
  exp_samples <- as.numeric(ars(n, function(x) dexp(x, rate = 2),
                                lower = 0, upper = Inf))
  exp_mean <- mean(exp_samples)
  exp_sd <- sd(exp_samples)
  exp_ks <- suppressWarnings(ks.test(exp_samples, "pexp", rate = 2)$p.value)
  exp_pass <- abs(exp_mean - 0.5) < 0.1 &&
    abs(exp_sd - 0.5) < 0.1 && exp_ks > 1e-3
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_EXPONENTIAL_DISTRIBUTION", exp_pass,
                    exp_mean, exp_sd,
                    sprintf("target mean 0.5, target sd 0.5, KS p-value %.4g",
                            exp_ks))

  # -----------------------------------------------------------------------
  cat("\n[7] Unnormalised expression input\n")
  cat("  Drawing", n, "samples from exp(-x^2/2) ...\n")
  expr_samples <- as.numeric(ars(n, "exp(-x^2/2)"))
  expr_mean <- mean(expr_samples)
  expr_sd <- sd(expr_samples)
  expr_ks <- suppressWarnings(ks.test(expr_samples, "pnorm")$p.value)
  expr_pass <- abs(expr_mean) < 0.1 &&
    abs(expr_sd - 1) < 0.1 && expr_ks > 1e-3
  results[[length(results) + 1L]] <-
    ars_test_report("TEST_EXPRESSION_INPUT", expr_pass,
                    expr_mean, expr_sd,
                    sprintf("target mean 0, target sd 1, KS p-value %.4g",
                            expr_ks))

  # -----------------------------------------------------------------------
  if (write_files) {
    writeLines(format(normal_samples, digits = 15),
               "/app/normal_samples.txt")
    writeLines(format(exp_samples, digits = 15),
               "/app/exponential_samples.txt")
    cat("\nWrote /app/normal_samples.txt and /app/exponential_samples.txt\n")
  }

  out <- do.call(rbind, results)
  n_pass <- sum(out$passed)
  cat("\n=====================================\n")
  cat(sprintf("Summary: %d of %d tests passed\n", n_pass, nrow(out)))
  invisible(out)
}

